module DigitFinder(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [15:0] denominations [0:7],\n    input [4:0] k,\n    output reg [4:0] count,\n    output reg [4:0] remainders [0:31],\n    output reg done\n);\n    // State declarations\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] INIT_GCD    = 4'd1;\n    localparam [3:0] CHECK_DENOM = 4'd2;\n    localparam [3:0] GCD_LOAD    = 4'd3;\n    localparam [3:0] GCD_LOOP    = 4'd4;\n    localparam [3:0] COMP_COUNT  = 4'd5;\n    localparam [3:0] GEN_REM     = 4'd6;\n    localparam [3:0] DONE_STATE  = 4'd7;\n    reg [3:0] state;\n    // Internal registers\n    reg [15:0] current_g;\n    reg [15:0] a_reg, b_reg;\n    reg [3:0] denom_index;\n    reg final_gcd_flag;\n    reg [7:0] i;  // Counter for GEN_REM\n    reg [7:0] cycle_counter;\n    // Constants\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    integer idx;  // For loop variable\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            current_g <= 16'd0;\n            denom_index <= 4'd0;\n            a_reg <= 16'd0;\n            b_reg <= 16'd0;\n            cycle_counter <= 8'd0;\n            final_gcd_flag <= 1'b0;\n            count <= 5'd0;\n            i <= 8'd0;\n            for (idx = 0; idx < 32; idx = idx + 1) begin\n                remainders[idx] <= 5'd0;\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        if (n == 4'd0) begin\n                            current_g <= 16'd0;\n                            denom_index <= 4'd0;\n                            state <= CHECK_DENOM;\n                        end else begin\n                            current_g <= denominations[0];\n                            denom_index <= 4'd1;\n                            state <= CHECK_DENOM;\n                        end\n                    end\n                end\n                CHECK_DENOM: begin\n                    if (cycle_counter >= MAX_CYCLES) begin\n                        state <= DONE_STATE;\n                    end else if (denom_index >= n) begin\n                        final_gcd_flag <= 1'b1;\n                        a_reg <= current_g;\n                        b_reg <= {11'd0, k};\n                        state <= GCD_LOAD;\n                    end else begin\n                        final_gcd_flag <= 1'b0;\n                        a_reg <= current_g;\n                        b_reg <= denominations[denom_index];\n                        state <= GCD_LOAD;\n                    end\n                end\n                GCD_LOAD: begin\n                    state <= GCD_LOOP;\n                end\n                GCD_LOOP: begin\n                    if (b_reg == 16'd0) begin\n                        if (final_gcd_flag) begin\n                            current_g <= a_reg;\n                            state <= COMP_COUNT;\n                        end else begin\n                            current_g <= a_reg;\n                            denom_index <= denom_index + 4'd1;\n                            state <= CHECK_DENOM;\n                        end\n                    end else if (a_reg >= b_reg) begin\n                        a_reg <= a_reg - b_reg;\n                    end else begin\n                        a_reg <= b_reg;\n                        b_reg <= a_reg;\n                    end\n                end\n                COMP_COUNT: begin\n                    if (current_g == 16'd0) begin\n                        count <= 5'd0;\n                    end else begin\n                        count <= k / current_g[4:0];\n                    end\n                    i <= 8'd0;\n                    state <= GEN_REM;\n                end\n                GEN_REM: begin\n                    if (i < count) begin\n                        remainders[i] <= i[4:0] * current_g[4:0];\n                        i <= i + 8'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule